1	package credit
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"strings"
8		"unicode/utf8"
9	)
10	
11	// duplicateFieldError 表示同一个 JSON 对象内出现了读取功能无法确定归属的
12	// 两个字段：
13	//   - 字段名完全相同（first == second，如两份 "credit"）；
14	//   - 两个字段名只有大小写差异（编码/json 的大小写折叠等同于
15	//     strings.EqualFold），却都被现有读取功能识别为同一条记录字段
16	//     （如 "credit" 与 "Credit" 都填入课程学分，"courses" 与
17	//     "COURSES" 都填入最外层课程列表）。
18	//
19	// field 是两者共同指向的规范字段名（结构体 json 标签原文）；完全同名时
20	// 与 first、second 相同。
21	type duplicateFieldError struct {
22		field  string
23		first  string
24		second string
25	}
26	
27	func (e *duplicateFieldError) Error() string {
28		if e.first == e.second {
29			return fmt.Sprintf("同一 JSON 对象内字段名 %q 重复出现，字段归属无法确定", e.first)
30		}
31		return fmt.Sprintf(
32			"同一 JSON 对象内字段名 %q 与 %q 仅大小写不同，读取时都指向同一记录字段 %q，字段归属无法确定",
33			e.first, e.second, e.field)
34	}
35	
36	// objKind 标识一个 JSON 对象在记录格式中的位置，用于确定该对象有哪些
37	// “能被现有读取功能识别”的字段名。
38	type objKind int
39	
40	const (
41		objUnknown     objKind = iota // 不属于记录格式的对象（交由结构体解码按未知字段/类型拒绝）
42		objFile                       // 记录最外层 fileData
43		objCourse                     // courses 数组元素：课程
44		objStudent                    // students 数组元素：学生
45		objRequirement                // requirements 数组元素：课程要求
46		objEnrollment                 // enrollments 数组元素：修读
47		objWaiver                     // waivers 数组元素：免修
48	)
49	
50	// recognizedFields 是各类对象能被读取功能识别的字段名（结构体 json 标签
51	// 原文）。标签名必须与 fileData 及各记录结构体上的 json 标签保持一致。
52	// 同一对象的标签在大小写不敏感比较下两两不同（否则该格式本身就有歧义）。
53	var recognizedFields = map[objKind][]string{
54		objFile: {
55			"version", "courses", "students", "requirements",
56			"enrollments", "waivers", "nextResultSeq",
57		},
58		objCourse:      {"id", "name", "credit", "open"},
59		objStudent:     {"id"},
60		objRequirement: {"id", "student", "course"},
61		objEnrollment:  {"id", "student", "req", "term", "result", "resultSeq"},
62		objWaiver:      {"id", "student", "req", "basis", "status", "reason"},
63	}
64	
65	// matchRecordField 报告键名 key 是否会被现有读取功能填入 kind 对象的某个
66	// 记录字段，命中时返回该字段的规范名称（json 标签原文）。
67	//
68	// encoding/json 解进结构体时先按精确名匹配，不中再按大小写折叠名匹配，
69	// 折叠规则等同于 strings.EqualFold（完整 Unicode 简单折叠，而非仅 ASCII：
70	// 例如 U+212A“K”折到 k、U+0130“İ”折到 i）。这里照搬同一判定，才能保证
71	// “两个键名被现有读取功能识别为同一字段”的口径与实际解码完全一致——
72	// 任何大小写或 Unicode 转义组合都无法让一个键绕过本扫描却仍被解码器接受。
73	func matchRecordField(kind objKind, key string) (string, bool) {
74		for _, tag := range recognizedFields[kind] {
75			if strings.EqualFold(key, tag) {
76				return tag, true
77			}
78		}
79		return "", false
80	}
81	
82	// fileKeyObjectKind 给出最外层对象某个键所对应数组元素/嵌套对象的类型。
83	// 记录格式里只有最外层的五个数组承载记录对象。键名同样按“能否被读取功能
84	// 识别”为准：大小写折叠后等于 courses 的键（如 COURSES）解出来仍是课程
85	// 列表，其元素必须按课程对象检查，不能借顶层键的大小写写法绕过限制。
86	func fileKeyObjectKind(key string) objKind {
87		if canonical, ok := matchRecordField(objFile, key); ok {
88			switch canonical {
89			case "courses":
90				return objCourse
91			case "students":
92				return objStudent
93			case "requirements":
94				return objRequirement
95			case "enrollments":
96				return objEnrollment
97			case "waivers":
98				return objWaiver
99			}
100		}
101		return objUnknown
102	}
103	
104	// scanDuplicateKeys 扫描第一份完整 JSON 值的 token 流，在每个对象内检查
105	// 字段归属唯一；第一份值之后的字节一律不读（调用方另行检查完整记录之后
106	// 是否还拼接了多余内容，那里的报错信息需要与本检查区分开）。
107	//
108	// 背景：encoding/json 直接解进结构体（或 map）时，同一对象内的重复键会被
109	// 后一个静默覆盖，而且结构体字段按大小写折叠匹配 json 标签（规则等同于
110	// strings.EqualFold）——同一门课程同时写 "credit":4 与 "Credit":9 时，
111	// 标准库读不出“曾经写过两个”，学分直接被后一个值顶替，两个键先后颠倒
112	// 结果也随之颠倒。因此在正常结构体解码之前先单独扫描一遍 token 流。
113	//
114	// 规则：
115	//   - 同一个 JSON 对象内字段归属只能确定一次：完全同名的两个键，或两个
116	//     键名在大小写折叠后都指向同一条可识别记录字段（如 credit 与
117	//     Credit、student 与 Student、courses 与 COURSES），发现即返回
118	//     *duplicateFieldError（含规范字段名与两个原始写法）。
119	//   - 字段顺序、是否相邻、两个值是否相同都不影响判定。
120	//   - 比较以 JSON 解码后的文字为准：Token() 返回的键名已完成 Unicode
121	//     反转义，所以 "credit"、它的 \uXXXX 转义写法与 "Credit" 之间任意
122	//     两两组合都按解码后实际所指的字段判断，不能用转义加大小写的组合
123	//     绕开限制。
124	//   - 限制只针对同一对象：对象与数组可任意嵌套，数组各元素、不同课程或
125	//     不同学生等不同对象各自携带同名字段是正常结构，互不比较。
126	//   - 不能被读取功能识别的字段不参与折叠归并，但完全同名仍按重复拒绝；
127	//     真正的未知字段留给随后的 DisallowUnknownFields 解码阶段拒绝。
128	//   - 字符串“值”里出现字段名（依据、课程名称等）不是键，不参与检查。
129	func scanDuplicateKeys(r io.Reader) error {
130		type frame struct {
131			isObj bool
132			// kind 标识对象类型（决定有哪些可识别字段）；数组帧不用。
133			kind objKind
134			// elem 标识数组元素对象的类型（数组帧使用）。
135			elem objKind
136			// expectKey 仅对对象有意义：true 表示下一个字符串 token 是键
137			// （或直接遇到 '}'）；false 表示正在等待该键所对应的值。
138			// 对象内 token 天然按键、值、键、值交替（逗号不产生 token），
139			// 借此区分字符串 token 是键还是普通字符串值。
140			expectKey bool
141			// pendingKey 是当前值所属的键，用于判断嵌套对象/数组的类型。
142			pendingKey string
143			// rawKeys 记录该对象内出现过的全部原始键名（解码后文字）。
144			rawKeys map[string]struct{}
145			// seen 记录每条可识别记录字段第一次出现时的原始写法，以规范
146			// 字段名为索引；无法识别的键不进此表。
147			seen map[string]string
148		}
149		var stack []frame
150		depth := 0
151	
152		push := func(d json.Delim) {
153			switch d {
154			case '{':
155				kind := objUnknown
156				if n := len(stack); n == 0 {
157					// 第一份值的根对象即记录最外层；根值不是对象时结构体
158					// 解码阶段自会按类型拒绝。
159					kind = objFile
160				} else if p := &stack[n-1]; p.isObj {
161					if p.kind == objFile {
162						kind = fileKeyObjectKind(p.pendingKey)
163					}
164				} else {
165					// 对象在数组里：类型由承载它的数组决定（数组类型又由
166					// 最外层五个字段之一决定）。
167					kind = stack[n-1].elem
168				}
169				stack = append(stack, frame{
170					isObj: true, kind: kind, expectKey: true,
171					rawKeys: map[string]struct{}{},
172					seen:    map[string]string{},
173				})
174			case '[':
175				elem := objUnknown
176				if n := len(stack); n > 0 {
177					if p := &stack[n-1]; p.isObj {
178						if p.kind == objFile {
179							elem = fileKeyObjectKind(p.pendingKey)
180						}
181					} else {
182						// 数组嵌套：内层数组元素类型跟随外层数组。
183						elem = p.elem
184					}
185				}
186				stack = append(stack, frame{isObj: false, elem: elem})
187			}
188		}
189		// valueEnded 通知栈顶对象：刚读完一个值（标量或嵌套结构的结束括号）。
190		valueEnded := func() {
191			if n := len(stack); n > 0 {
192				f := &stack[n-1]
193				if f.isObj && !f.expectKey {
194					f.expectKey = true
195					f.pendingKey = ""
196				}
197			}
198		}
199	
200		dec := json.NewDecoder(r)
201		for {
202			tok, err := dec.Token()
203			if err == io.EOF {
204				// 空输入交由后续结构体解码报错（空文件在更前面已被拒绝）。
205				return nil
206			}
207			if err != nil {
208				return err
209			}
210			switch t := tok.(type) {
211			case json.Delim:
212				switch t {
213				case '{', '[':
214					depth++
215					push(t)
216				case '}', ']':
217					depth--
218					stack = stack[:len(stack)-1]
219					if depth == 0 {
220						// 唯一的顶层值已完整读完，其后内容不在本检查范围。
221						return nil
222					}
223					// 刚结束的嵌套对象/数组本身就是外层键所对应的值。
224					valueEnded()
225				}
226			case string:
227				n := len(stack)
228				if n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
229					f := &stack[n-1]
230					// 对象键：Token() 已按解码后的文字返回，\uXXXX 转义
231					// 形式的键名与直接写出的同名键在这里完全不可区分。
232					if _, dup := f.rawKeys[t]; dup {
233						return &duplicateFieldError{field: t, first: t, second: t}
234					}
235					f.rawKeys[t] = struct{}{}
236					// 只有指向同一条可识别记录字段的不同写法才算归属
237					// 冲突；未知键的大小写变体随后由结构体解码按未知字段
238					// 拒绝（如 "foo" 与 "Foo" 不会被当成任何业务字段）。
239					if canonical, known := matchRecordField(f.kind, t); known {
240						if prev, conflict := f.seen[canonical]; conflict {
241							return &duplicateFieldError{
242								field:  canonical,
243								first:  prev,
244								second: t,
245							}
246						}
247						f.seen[canonical] = t
248					}
249					f.expectKey = false
250					f.pendingKey = t
251					continue
252				}
253				valueEnded()
254				if depth == 0 {
255					return nil // 顶层标量值
256				}
257			default:
258				// number、bool、nil 等标量值。
259				valueEnded()
260				if depth == 0 {
261					return nil
262				}
263			}
264		}
265	}
266	
267	// scanStringUnicode 按原始字节扫描第一份完整 JSON 值里的全部字符串
268	// （字段名与字段值），验证每个字符串都能还原为合法 Unicode 文字：
269	//   - 字符串中直接写入的字节必须是合法 UTF-8；
270	//   - \uXXXX 转义中的高位代理项（U+D800–U+DBFF）必须紧跟一个低位代理项
271	//     （U+DC00–U+DFFF）转义；孤立的低位代理项同样非法。
272	//
273	// 背景：encoding/json 解码时会把非法 UTF-8 字节与未配对的代理项转义静默
274	// 替换成 U+FFFD（“�”）。替换后的学生编号、课程名称或免修依据绝不能被当成
275	// 正常内容继续查询、核对或登记——两个本来不同的编号可能被替换成同一个
276	// 而被误判重复或误判相同。因此必须在结构体解码之前按原始字节拒绝这样的
277	// 文件，整份判为内容损坏，哪怕问题只在一条已拒绝免修的依据里、或在与本次
278	// 核对无关的课程名称里。
279	//
280	// 合法文字不受影响：中文、直接写入的补充平面字符、完整的高低代理项转义对、
281	// 用转义表达的控制字符都保留原意；用户确实写入的“�”（U+FFFD，直接写出
282	// 或 \uFFFD 转义）也是合法文字，不能仅因解码结果含有它就拒绝文件。
283	//
284	// 与 scanDuplicateKeys 一样只扫描第一份完整值：完整记录之后的多余内容
285	// 本来就会被读取方拒绝，无需在此重复判定。
286	func scanStringUnicode(raw []byte) error {
287		i := 0
288		for i < len(raw) && isJSONSpace(raw[i]) {
289			i++
290		}
291		if i >= len(raw) {
292			return nil // 空输入交由后续结构体解码报错
293		}
294		switch raw[i] {
295		case '"':
296			// 顶层就是一个字符串：扫描它本身即可。
297			_, err := scanJSONString(raw, i)
298			return err
299		case '{', '[':
300		default:
301			return nil // 顶层标量（数字、true、false、null）不含字符串
302		}
303		depth := 0
304		for i < len(raw) {
305			switch raw[i] {
306			case '"':
307				j, err := scanJSONString(raw, i)
308				if err != nil {
309					return err
310				}
311				i = j
312			case '{', '[':
313				depth++
314				i++
315			case '}', ']':
316				depth--
317				i++
318				if depth == 0 {
319					// 唯一的顶层值已完整读完，其后内容不在本检查范围。
320					return nil
321				}
322			default:
323				i++
324			}
325		}
326		return nil // 未闭合的结构由 JSON 解析报错
327	}
328	
329	// scanJSONString 扫描从 raw[start]（必须是 '"'）开始的一个字符串字面量，
330	// 返回结束引号之后的下标。字符串内容无法还原为合法 Unicode 文字时报错；
331	// 未闭合、非法转义形式等语法问题留给 JSON 解析器报告，本函数不为此报错。
332	func scanJSONString(raw []byte, start int) (int, error) {
333		i := start + 1
334		for i < len(raw) {
335			c := raw[i]
336			switch {
337			case c == '"':
338				return i + 1, nil
339			case c == '\\':
340				if i+1 >= len(raw) {
341					return len(raw), nil
342				}
343				if raw[i+1] != 'u' {
344					i += 2 // 其他转义的合法性由 JSON 解析器校验
345					continue
346				}
347				v, ok := hex4(raw, i+2)
348				if !ok {
349					i += 2 // 非法 \u 转义形式由 JSON 解析器报错
350					continue
351				}
352				switch {
353				case isHighSurrogate(v):
354					// 高位代理项必须紧跟一个 \uXXXX 形式的低位代理项转义。
355					if i+12 <= len(raw) && raw[i+6] == '\\' && raw[i+7] == 'u' {
356						if v2, ok := hex4(raw, i+8); ok && isLowSurrogate(v2) {
357							i += 12
358							continue
359						}
360					}
361					return 0, fmt.Errorf(
362						`高位代理项转义 \u%04X 后没有紧跟低位代理项转义`, v)
363				case isLowSurrogate(v):
364					return 0, fmt.Errorf(
365						`低位代理项转义 \u%04X 没有对应的高位代理项转义`, v)
366				default:
367					i += 6
368				}
369			case c < utf8.RuneSelf:
370				i++
371			default:
372				// 直接写入的多字节字符必须是合法 UTF-8。注意 U+FFFD 本身
373				// 是合法文字：只有解码失败（size 为 1）才拒绝。
374				r, size := utf8.DecodeRune(raw[i:])
375				if r == utf8.RuneError && size == 1 {
376					return 0, fmt.Errorf(
377						"字符串中直接写入的字节 0x%02X 不是合法 UTF-8", c)
378				}
379				i += size
380			}
381		}
382		return i, nil // 未闭合的字符串由 JSON 解析器报错
383	}
384	
385	func isJSONSpace(c byte) bool {
386		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
387	}
388	
389	func isHighSurrogate(r rune) bool { return 0xD800 <= r && r <= 0xDBFF }
390	func isLowSurrogate(r rune) bool  { return 0xDC00 <= r && r <= 0xDFFF }
391	
392	// hex4 把 b[i:i+4] 读作四位十六进制数。
393	func hex4(b []byte, i int) (rune, bool) {
394		if i+4 > len(b) {
395			return 0, false
396		}
397		var v rune
398		for k := 0; k < 4; k++ {
399			c := b[i+k]
400			var d byte
401			switch {
402			case '0' <= c && c <= '9':
403				d = c - '0'
404			case 'a' <= c && c <= 'f':
405				d = c - 'a' + 10
406			case 'A' <= c && c <= 'F':
407				d = c - 'A' + 10
408			default:
409				return 0, false
410			}
411			v = v*16 + rune(d)
412		}
413		return v, true
414	}
