1	package credit
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// 以下常量是 JSON 源文本中的转义写法（Go 解释字符串里的 \\u 即字面反斜杠+u），
12	// 两种写法经 JSON 解码后都得到键名 "credit"。
13	const (
14		escapedCreditKey    = "\"\\u0063redit\"" // JSON 解码后为 "credit"，仅首字母转义
15		escapedCreditKeyAlt = "\"c\\u0072edit\"" // JSON 解码后为 "credit"，仅第二个字母转义
16		escapedAKey         = "\"a\\u0030\""     // JSON 解码后为 "a0"
17	)
18	
19	// TestLoadRejectsDuplicateObjectFields 同一 JSON 对象内字段名重复时，无论
20	// 重复的是学分、学生编号还是其他字段，无论两个值是否相同、是否相邻，整份
21	// 文件都必须判为内容损坏：Load 报错（错误点名文件与重复字段）、标记文件
22	// 已存在，且原文件每个字节原样保留。绝不能让后一个值静默顶替前一个值。
23	func TestLoadRejectsDuplicateObjectFields(t *testing.T) {
24		cases := map[string]struct {
25			content string
26			field   string
27		}{
28			"课程学分重复且值不同": {
29				`{"version":1,"courses":[` +
30					`{"id":"c1","name":"数学","credit":4,"credit":9,"open":true}]}` + "\n",
31				"credit",
32			},
33			"课程学分重复但值相同": {
34				`{"version":1,"courses":[` +
35					`{"id":"c1","name":"数学","credit":4,"credit":4,"open":true}]}` + "\n",
36				"credit",
37			},
38			"学分字段不相邻重复": {
39				`{"version":1,"courses":[` +
40					`{"credit":4,"id":"c1","name":"数学","open":true,"credit":5}]}` + "\n",
41				"credit",
42			},
43			"修读记录学生编号重复": {
44				`{"version":1,"students":[{"id":"s1"},{"id":"s2"}],"enrollments":[` +
45					`{"id":"e1","student":"s1","student":"s2","req":"r1",` +
46					`"term":"2024春","result":"enrolled"}]}` + "\n",
47				"student",
48			},
49			"要求记录学生编号重复": {
50				`{"version":1,"students":[{"id":"s1"}],"courses":[` +
51					`{"id":"c1","name":"数学","credit":4,"open":true}],"requirements":[` +
52					`{"id":"r1","student":"s1","course":"c1","student":"s1"}]}` + "\n",
53				"student",
54			},
55			"免修记录学生编号重复": {
56				`{"version":1,"students":[{"id":"s1"}],"waivers":[` +
57					`{"id":"w1","student":"s1","student":"s1","req":"r1",` +
58					`"basis":"竞赛获奖","status":"rejected",` +
59					`"reason":"目标要求 r1 不存在或不属于该学生"}]}` + "\n",
60				"student",
61			},
62			"顶层courses重复且第二份为空数组": {
63				`{"version":1,"courses":[{"id":"c1","name":"数学","credit":4,"open":true}],` +
64					`"courses":[]}` + "\n",
65				"courses",
66			},
67			"顶层version重复": {
68				`{"version":1,"version":1}` + "\n",
69				"version",
70			},
71			"数组第二条记录内重复": {
72				`{"version":1,"students":[{"id":"s1"},{"id":"s2","id":"s3"}]}` + "\n",
73				"id",
74			},
75			"Unicode转义键名与直接书写重复": {
76				`{"version":1,"courses":[` +
77					`{"id":"c1","name":"数学","credit":4,` + escapedCreditKey + `:9,"open":true}]}` + "\n",
78				"credit",
79			},
80			"两种Unicode写法同名键重复": {
81				`{"version":1,"courses":[` +
82					`{"id":"c1","name":"数学",` + escapedCreditKey + `:4,` + escapedCreditKeyAlt + `:9,"open":true}]}` + "\n",
83				"credit",
84			},
85			"免修依据字段重复": {
86				`{"version":1,"students":[{"id":"s1"}],"waivers":[` +
87					`{"id":"w1","student":"s1","req":"r1","basis":"依据甲",` +
88					`"basis":"依据乙","status":"rejected","reason":"x"}]}` + "\n",
89				"basis",
90			},
91		}
92		for name, tc := range cases {
93			t.Run(name, func(t *testing.T) {
94				path := filepath.Join(t.TempDir(), "records.json")
95				if err := os.WriteFile(path, []byte(tc.content), 0o600); err != nil {
96					t.Fatal(err)
97				}
98				s, existed, err := Load(path)
99				if err == nil {
100					t.Fatalf("重复字段文件必须拒绝读取，却得到 store=%v", s)
101				}
102				if !existed {
103					t.Fatal("损坏文件应标记为已存在")
104				}
105				msg := err.Error()
106				if !strings.Contains(msg, path) {
107					t.Fatalf("错误信息应点名所读文件，得到：%v", err)
108				}
109				if !strings.Contains(msg, "内容损坏") {
110					t.Fatalf("错误信息应说明内容损坏，得到：%v", err)
111				}
112				if !strings.Contains(msg, tc.field) {
113					t.Fatalf("错误信息应指出重复字段名 %q，得到：%v", tc.field, err)
114				}
115				var dupErr *duplicateFieldError
116				if errors.As(err, &dupErr) {
117					t.Fatalf("Load 返回的错误不应泄露内部扫描错误类型，得到 %T", err)
118				}
119				got, readErr := os.ReadFile(path)
120				if readErr != nil {
121					t.Fatal(readErr)
122				}
123				if string(got) != tc.content {
124					t.Fatalf("拒绝读取不得改动原文件\nwant=%q\n got=%q", tc.content, got)
125				}
126			})
127		}
128	}
129	
130	// TestLoadAllowsSameFieldAcrossDifferentObjects 限制只针对同一个对象：
131	// 不同课程各有 credit、不同学生名下各自的同号要求/修读/免修，以及字符串
132	// 内容里提到字段名，都必须照常读取，学分与归属规则保持原样。
133	func TestLoadAllowsSameFieldAcrossDifferentObjects(t *testing.T) {
134		content := `{
135	  "version": 1,
136	  "courses": [
137	    {"id": "c1", "name": "credit 字段简介", "credit": 4, "open": true},
138	    {"id": "c2", "name": "student 编号说明", "credit": 9, "open": true}
139	  ],
140	  "students": [{"id": "s1"}, {"id": "s2"}],
141	  "requirements": [
142	    {"id": "r1", "student": "s1", "course": "c1"},
143	    {"id": "r1", "student": "s2", "course": "c2"}
144	  ],
145	  "enrollments": [
146	    {"id": "e1", "student": "s1", "req": "r1", "term": "2024春",
147	     "result": "passed", "resultSeq": 1},
148	    {"id": "e1", "student": "s2", "req": "r1", "term": "2024春",
149	     "result": "enrolled"}
150	  ],
151	  "waivers": [
152	    {"id": "w1", "student": "s2", "req": "r1", "basis": "材料中提到 student 字段",
153	     "status": "rejected", "reason": "该要求已有有效免修 w9"}
154	  ],
155	  "nextResultSeq": 1
156	}
157	`
158		path := filepath.Join(t.TempDir(), "records.json")
159		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
160			t.Fatal(err)
161		}
162		s, existed, err := Load(path)
163		if err != nil || !existed {
164			t.Fatalf("跨对象同名字段应正常读取：existed=%v err=%v", existed, err)
165		}
166		// 两门课各自的学分不得串行。
167		if c := s.Course("c1"); c == nil || c.Credit != 4 {
168			t.Fatalf("c1 应为 4 学分，得到 %+v", c)
169		}
170		if c := s.Course("c2"); c == nil || c.Credit != 9 {
171			t.Fatalf("c2 应为 9 学分，得到 %+v", c)
172		}
173		// 同号修读各归各：s1 通过计 4 学分；s2 仍选课，且 c2 停开不影响读取。
174		if rep := s.CheckStudent("s1"); rep.TotalCredits != 4 {
175			t.Fatalf("s1 应得 4 学分，得到 %d", rep.TotalCredits)
176		}
177		if rep := s.CheckStudent("s2"); rep.TotalCredits != 0 || len(rep.Unmet) != 1 {
178			t.Fatalf("s2 应为 0 学分且要求未满足，得到 %+v", rep)
179		}
180		if e := s.Enrollment("s2", "e1"); e == nil || e.Result != Enrolled {
181			t.Fatalf("s2 的同号修读应保持选课归属：%+v", e)
182		}
183		if w := s.Waiver("s2", "w1"); w == nil || w.Status != WaiverRejected ||
184			!strings.Contains(w.Basis, "student 字段") {
185			t.Fatalf("s2 的免修历史应原样保留（依据文字含字段名也合法）：%+v", w)
186		}
187	}
188	
189	// TestLoadDuplicateFixedFileWorksNormally 修正重复字段后的合法记录仍可通过
190	// 原有入口正常使用：以第一份学分 4 为准修复后，核对与后续登记行为不变。
191	func TestLoadDuplicateFixedFileWorksNormally(t *testing.T) {
192		fixed := `{"version":1,"courses":[` +
193			`{"id":"c1","name":"数学","credit":4,"open":true}],` +
194			`"students":[{"id":"s1"}],` +
195			`"requirements":[{"id":"r1","student":"s1","course":"c1"}],` +
196			`"enrollments":[{"id":"e1","student":"s1","req":"r1","term":"2024春",` +
197			`"result":"passed","resultSeq":1}],"waivers":[],"nextResultSeq":1}` + "\n"
198		path := filepath.Join(t.TempDir(), "records.json")
199		if err := os.WriteFile(path, []byte(fixed), 0o600); err != nil {
200			t.Fatal(err)
201		}
202		s, _, err := Load(path)
203		if err != nil {
204			t.Fatalf("修正后的文件应可正常读取：%v", err)
205		}
206		if rep := s.CheckStudent("s1"); rep.TotalCredits != 4 {
207			t.Fatalf("修复后应按 4 学分核对，得到 %d", rep.TotalCredits)
208		}
209		// 既有写入路径仍正常工作。
210		if _, _, err := s.AddStudent("s2"); err != nil {
211			t.Fatalf("修复后继续登记应正常：%v", err)
212		}
213	}
214	
215	// TestScanDuplicateKeys 直接覆盖扫描器的边界情形。
216	func TestScanDuplicateKeys(t *testing.T) {
217		okCases := map[string]string{
218			"空对象":            `{}`,
219			"空数组":            `[]`,
220			"无重复对象":          `{"a":1,"b":[1,2,{"c":"x"}]}`,
221			"数组各元素同名键":       `[{"a":1},{"a":2}]`,
222			"字符串值里出现字段名":     `{"a":"b, b again","b":1}`,
223			"嵌套对象内外同名字段":     `{"a":{"a":1},"b":2}`,
224			"空字符串键与值":        `{"":"","x":""}`,
225			"Unicode转义后仍不同名": `{` + escapedAKey + `:1,"b":1}`,
226			"键名含转义引号与控制符":    `{"a\"b":1,"a\b":2}`,
227			"对象在数组深层":        `[[[{"a":1}]],{"b":2}]`,
228			"标量顶层值":          `42`,
229			"记录前后有空白":        "\n\t {\"a\":1} \r\n",
230			"首份值之后的重复键不予扫描":  `{"a":1}{"a":1,"a":2}`,
231		}
232		for name, in := range okCases {
233			t.Run("合法/"+name, func(t *testing.T) {
234				if err := scanDuplicateKeys(strings.NewReader(in)); err != nil {
235					t.Fatalf("不应报重复，得到 %v（输入 %q）", err, in)
236				}
237			})
238		}
239	
240		dupCases := map[string]string{
241			"对象内直接重复":     `{"a":1,"a":2}`,
242			"嵌套对象内重复":     `{"x":{"a":1,"a":2}}`,
243			"数组元素对象内重复":   `[{"a":1,"a":2}]`,
244			"重复键不相邻":      `{"a":1,"b":2,"c":3,"a":4}`,
245			"值相同仍重复":      `{"a":{"x":1},"a":{"x":1}}`,
246			"转义键名与直接书写同名": `{"credit":4,` + escapedCreditKey + `:9}`,
247			"两种转义写法同名":    `{` + escapedCreditKey + `:4,` + escapedCreditKeyAlt + `:9}`,
248			"深层嵌套重复":      `{"x":[{"y":{"z":1,"z":2}}]}`,
249			"内外层同时重复必然报错": `{"a":1,"b":{"k":1,"k":2},"a":2}`,
250		}
251		for name, in := range dupCases {
252			t.Run("重复/"+name, func(t *testing.T) {
253				err := scanDuplicateKeys(strings.NewReader(in))
254				if err == nil {
255					t.Fatalf("应报重复字段（输入 %q）", in)
256				}
257				var dupErr *duplicateFieldError
258				if !errors.As(err, &dupErr) || dupErr.field == "" {
259					t.Fatalf("应返回带字段名的 duplicateFieldError，得到 %T: %v", err, err)
260				}
261			})
262		}
263	
264		// 扫描器只负责发现重复字段：值尚未读完就遇到 EOF 时不报“重复”，
265		// 语法残缺由 Load 中随后的普通结构体解码阶段判为损坏。
266		if err := scanDuplicateKeys(strings.NewReader(`{"a":`)); err != nil {
267			var dupErr *duplicateFieldError
268			if errors.As(err, &dupErr) {
269				t.Fatalf("残缺 JSON 不应被误报为重复字段，得到 %v", err)
270			}
271		}
272		if err := scanDuplicateKeys(strings.NewReader("")); err != nil {
273			t.Fatalf("空输入不在扫描阶段报错（交由调用方），得到 %v", err)
274		}
275	}
