289				`{"courses":[],"COURSES":[]}`, "courses", "courses", "COURSES",
290			},
291			"转义大写与直接小写": {
292				`{"version":1,"courses":[{"credit":4,` + escapedUpperCreditKey + `:9}]}`,
293				"credit", "credit", "Credit",
294			},
295			"转义小写与直接大写": {
296				`{"version":1,"courses":[{` + escapedCreditKey + `:4,"Credit":9}]}`,
297				"credit", "credit", "Credit",
298			},
299			"大写顶层数组内记录冲突": {
300				`{"COURSES":[{"credit":4,"Credit":9}]}`,
301				"credit", "credit", "Credit",
302			},
303			"嵌套数组深层记录冲突": {
304				`{"ENROLLMENTS":[[{"student":"s1","Student":"s2"}]]}`,
305				"student", "student", "Student",
306			},
307		}
308		for name, tc := range dupCases {
309			t.Run("冲突/"+name, func(t *testing.T) {
310				err := scanDuplicateKeys(strings.NewReader(tc.in))
311				var dupErr *duplicateFieldError
312				if !errors.As(err, &dupErr) {
313					t.Fatalf("应返回 duplicateFieldError（输入 %q），得到 %T: %v", tc.in, err, err)
314				}
315				if dupErr.field != tc.field || dupErr.first != tc.first || dupErr.second != tc.second {
316					t.Fatalf("冲突信息不符：got (%q,%q,%q) want (%q,%q,%q)",
317						dupErr.field, dupErr.first, dupErr.second,
