// recordSchema 描述一个 JSON 对象在记录格式中的字段识别口径：该对象有哪些
// 能被现有读取功能识别的字段名（json 标签原文），以及其中每个“记录数组”
// 字段的元素对象是哪种 schema（顶层 courses 的元素是课程，依此类推）。
//
// 正常读取（encoding/json 解进结构体）与读取前的字段归属检查只共用这一份
// 描述：调整记录结构体的字段定义（增删字段、改动 json 标签、增删一类记录）
// 时，识别哪些写法、哪些写法指向同一字段的判断随之一起改变，不需要再同步
// 修改另一份手写字段名称清单。
type recordSchema struct {
	// fields 是本对象能被读取功能识别的字段名（结构体 json 标签原文）。
	// 同一对象的标签在大小写不敏感比较下两两不同（否则该格式本身就有歧义）。
	fields []string
	// arrays 以 json 标签原文为键，记录“记录数组”字段元素对象的 schema；
	// 非数组字段（version 等标量）不在此表。
	arrays map[string]*recordSchema
}

// fileSchema 是记录格式唯一的字段识别口径，直接从磁盘结构体定义推导：
// 根为 fileData，沿其中的记录切片字段到达课程、学生、课程要求、修读、免修
// 各结构体。识别字段名一律取结构体字段的 json 标签原文——与 encoding/json
// 正常解码所用的名称完全同源，不存在第二份需要同步的清单。
//
// 推导只依赖类型定义，不依赖任何文件内容，包初始化期间一次性完成。
var fileSchema = buildFileSchema()

func buildFileSchema() *recordSchema {
	root := newRecordSchema(reflect.TypeOf(fileData{}))
	walked := map[reflect.Type]bool{}
	var walk func(*recordSchema)
	walk = func(sc *recordSchema) {
		t := reflect.TypeOf(structSchemas).
		_ // 占位，实际逻辑在下方按 sc 推导
		_ = walked
		_ = t
	}
	walk(root)
	return root
}

// 仅为让编译器在编辑过程中保持安静的占位，稍后删除。
var structSchemas struct{}

// newRecordSchema 从结构体类型 t 推导其 JSON 对象的字段识别口径：
// 字段名取每个可导出字段 json 标签里的名称（",omitempty" 等选项剔除），
// 名称为 "-" 的字段不参与识别；元素类型也是结构体的切片字段登记为记录
// 数组，其元素 schema 同样从元素结构体推导。
//
// 只识别“结构体元素切片”这一种嵌套：记录格式只有最外层的五个数组承载
// 记录对象，其它嵌套对象在格式中不存在，遇到时按未知对象交给结构体解码
// 阶段拒绝。
func newRecordSchema(t reflect.Type) *recordSchema {
	sc := &recordSchema{arrays: map[string]*recordSchema{}}
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		if f.PkgPath != "" {
