148	//     键名在大小写折叠后都指向同一条可识别记录字段（如 credit 与
149	//     Credit、student 与 Student、courses 与 COURSES），发现即返回
150	//     *duplicateFieldError（含规范字段名与两个原始写法）。
151	//   - 字段顺序、是否相邻、两个值是否相同都不影响判定。
152	//   - 比较以 JSON 解码后的文字为准：Token() 返回的键名已完成 Unicode
153	//     反转义，所以 "credit"、它的 \uXXXX 转义写法与 "Credit" 之间任意
154	//     两两组合都按解码后实际所指的字段判断，不能用转义加大小写的组合
155	//     绕开限制。
156	//   - 限制只针对同一对象：对象与数组可任意嵌套，数组各元素、不同课程或
157	//     不同学生等不同对象各自携带同名字段是正常结构，互不比较。
158	//   - 不能被读取功能识别的字段不参与折叠归并，但完全同名仍按重复拒绝；
159	//     真正的未知字段留给随后的 DisallowUnknownFields 解码阶段拒绝。
160	//   - 字符串“值”里出现字段名（依据、课程名称等）不是键，不参与检查。
161	func scanDuplicateKeys(r io.Reader) error {
162		type frame struct {
163			isObj bool
164			// kind 标识对象类型（决定有哪些可识别字段）；数组帧不用。
165			kind objKind
166			// elem 标识数组元素对象的类型（数组帧使用）。
167			elem objKind
168			// expectKey 仅对对象有意义：true 表示下一个字符串 token 是键
169			// （或直接遇到 '}'）；false 表示正在等待该键所对应的值。
170			// 对象内 token 天然按键、值、键、值交替（逗号不产生 token），
171			// 借此区分字符串 token 是键还是普通字符串值。
172			expectKey bool
173			// pendingKey 是当前值所属的键，用于判断嵌套对象/数组的类型。
174			pendingKey string
175			// rawKeys 记录该对象内出现过的全部原始键名（解码后文字）。
176			rawKeys map[string]struct{}
177			// seen 记录每条可识别记录字段第一次出现时的原始写法，以规范
178			// 字段名为索引；无法识别的键不进此表。
179			seen map[string]string
