218					if p := &stack[n-1]; p.isObj {
219						elem = p.schema.arrayElementSchema(p.pendingKey)
220					} else {
221						// 数组嵌套：内层数组元素类型跟随外层数组。
222						elem = p.elem
223					}
224				}
225				stack = append(stack, frame{isObj: false, elem: elem})
