package credit

import (
	"reflect"
	"testing"
)

func TestTmpSchemaDerivation(t *testing.T) {
	want := map[string][]string{
		"file":   {"version", "courses", "students", "requirements", "enrollments", "waivers", "nextResultSeq"},
		"course": {"id", "name", "credit", "open"},
		"student": {"id"},
		"req":    {"id", "student", "course"},
		"enr":    {"id", "student", "req", "term", "result", "resultSeq"},
		"waiver": {"id", "student", "req", "basis", "status", "reason"},
	}
	if !reflect.DeepEqual(fileSchema.fields, want["file"]) {
		t.Fatalf("file fields=%v", fileSchema.fields)
	}
	elems := map[string]*recordSchema{}
	for k, v := range fileSchema.arrays {
		elems[k] = v
	}
	checks := []struct{ key, want string }{
		{"courses", "course"}, {"students", "student"}, {"requirements", "req"},
		{"enrollments", "enr"}, {"waivers", "waiver"},
	}
	for _, c := range checks {
		got := elems[c.key].fields
		if !reflect.DeepEqual(got, want[c.want]) {
			t.Fatalf("%s fields=%v want %v", c.key, got, want[c.want])
		}
		if elems[c.key].arrays != nil && len(elems[c.key].arrays) != 0 {
			t.Fatalf("record struct %s must declare no nested record arrays, got %v", c.key, elems[c.key].arrays)
		}
	}
	// 标量字段不产生数组元素 schema。
	if fileSchema.arrayElementSchema("version") != nil {
		t.Fatal("version 不是记录数组")
	}
	// 大小写折叠取数组元素。
	if fileSchema.arrayElementSchema("COURSES") != elems["courses"] {
		t.Fatal("COURSES 应折叠到课程数组")
	}
}

