// jsonTagName 取结构体字段 json 标签中逗号前的名称部分；没有标签时按
// encoding/json 的规则退化为字段名本身（当前记录格式的所有字段都显式
// 标注了标签，退化分支只是与标准库口径保持一致）。
func jsonTagName(f reflect.StructField) string {
	tag := f.Tag.Get("json")
	if tag == "" {
		return f.Name
	}
	name, _, _ := strings.Cut(tag, ",")
	return name
}

input.new_string:
// jsonFieldName 取结构体字段在 JSON 中的名称，规则与 encoding/json 完全
// 一致：标签缺失或名称为空（如 `json:",omitempty"`）时退化为 Go 字段名；
// 名称为 "-" 且没有选项（`json:"-"`）表示该字段不参与（skip=true），而
// `json:"-,"` 是一个名称恰为 "-" 的正常字段。
func jsonFieldName(f reflect.StructField) (name string, skip bool) {
	tag, ok := f.Tag.Lookup("json")
	if !ok {
		return f.Name, false
	}
	name, _, _ = strings.Cut(tag, ",")
	if name == "-" && !strings.Contains(tag, ",") {
		return "", true
	}
	if name == "" {
		return f.Name, false
	}
	return name, false
}

